pub(crate) fn descriptor_verify(cwd: &Path, cid: &str) -> JsonValue {
    run_json(
        cwd,
        [
            "program",
            "module",
            "protocol-descriptor",
            "verify",
            cid,
            "--format",
            "json",
        ],
    )
}

pub(crate) fn descriptor_verify_rejected(cwd: &Path, cid: &str) -> (JsonValue, String) {
    let output = run(
        cwd,
        [
            OsStr::new("program"),
            OsStr::new("module"),
            OsStr::new("protocol-descriptor"),
            OsStr::new("verify"),
            OsStr::new(cid),
            OsStr::new("--format"),
            OsStr::new("json"),
